function BookCoverCornerCutterMaker.init() BookCoverCornerCutterMaker.ironStock=18; BookCoverCornerCutterMaker.bronzeStock=14; BookCoverCornerCutterMaker.woodStock=10; BookCoverCornerCutterMaker.leatherStock=8; BookCoverCornerCutterMaker.silverStock=8; BookCoverCornerCutterMaker.goldStock=6; BookCoverCornerCutterMaker.jewelStock=4; BookCoverCornerCutterMaker.pearlStock=4; BookCoverCornerCutterMaker.productStock={}; BookCoverCornerCutterMaker.buildings={}; BookCoverCornerCutterMaker.maker=nil; BookCoverCornerCutterMaker.activeMaking={}; BookCoverCornerCutterMaker.totalProducts=0; BookCoverCornerCutterMaker.dayTimer=0; print("[BookCoverCornerCutterMaker] Royal Book Cover Corner Cutter Maker System initialized (6 products, 4 buildings)") end
function BookCoverCornerCutterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverCornerCutterMaker.maker={name=n or ("Roborezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Roborezar najet: %s (spretnost: %d)",BookCoverCornerCutterMaker.maker.name,s),"success") end; return true end
function BookCoverCornerCutterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverCornerCutterMaker.build(id) local ok,e=BookCoverCornerCutterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverCornerCutterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
