function BookCoverCornerCutterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverCornerCutterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverCornerCutterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverCornerCutterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverCornerCutterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverCornerCutterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverCornerCutterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverCornerCutterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverCornerCutterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverCornerCutterMaker.buildings==0 then return false,"Potrebna roborezna delavnica" end; if not BookCoverCornerCutterMaker.maker then return false,"Potreben roborezar" end; return true end
function BookCoverCornerCutterMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverCornerCutterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverCornerCutterMaker.ironStock=BookCoverCornerCutterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverCornerCutterMaker.bronzeStock=BookCoverCornerCutterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverCornerCutterMaker.woodStock=BookCoverCornerCutterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverCornerCutterMaker.leatherStock=BookCoverCornerCutterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverCornerCutterMaker.silverStock=BookCoverCornerCutterMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverCornerCutterMaker.goldStock=BookCoverCornerCutterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverCornerCutterMaker.jewelStock=BookCoverCornerCutterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverCornerCutterMaker.pearlStock=BookCoverCornerCutterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverCornerCutterMaker.maker then t=math.max(1,t-math.floor(BookCoverCornerCutterMaker.maker.skill/13)) end; table.insert(BookCoverCornerCutterMaker.activeMaking,{id="bookcovercornercutter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverCornerCutterMaker.completeMaking(m) local q=1.0+(BookCoverCornerCutterMaker.getQualityBonus()/100); if BookCoverCornerCutterMaker.maker then q=q+(BookCoverCornerCutterMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverCornerCutterMaker.productStock[m.productType]=(BookCoverCornerCutterMaker.productStock[m.productType] or 0)+m.quantity; BookCoverCornerCutterMaker.totalProducts=BookCoverCornerCutterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverCornerCutterMaker.maker then BookCoverCornerCutterMaker.maker.itemsMade=BookCoverCornerCutterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverCornerCutterMaker.maker.skill=math.min(100,BookCoverCornerCutterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Roborez izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcovercornercutter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverCornerCutterMaker.update(dt) if not _G.state then return end; BookCoverCornerCutterMaker.dayTimer=BookCoverCornerCutterMaker.dayTimer+dt; if BookCoverCornerCutterMaker.dayTimer>=30 then BookCoverCornerCutterMaker.dayTimer=0; for i=#BookCoverCornerCutterMaker.activeMaking,1,-1 do local m=BookCoverCornerCutterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverCornerCutterMaker.completeMaking(m); table.remove(BookCoverCornerCutterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverCornerCutterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverCornerCutterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
